#!/usr/bin/env python3
"""
恒生效能平台查询工具
用于查询需求、任务、版本信息，并生成报表
"""
import json
import sys
from typing import Optional, Dict, Any, List

# 默认产品编号
DEFAULT_PRODUCT_NO = "CP-S000128-3.2"
DEFAULT_PRODUCT_NAME = "恒生投资交易管理系统软件VO3.2"


def identify_query_type(query_value: str) -> Dict[str, str]:
    """
    根据查询值自动识别查询类型

    查询类型优先级：
    1. P开头 → 补丁编号（如P202509293019）
    2. T开头 → 任务编号
    3. ST/OST/ALGO开头 → 版本编号
    4. 纯数字 → 功能号 或 需求编号

    Args:
        query_value: 查询值

    Returns:
        包含type和field的字典
    """
    # 补丁编号：以P开头，如 P202509293019
    if query_value.startswith('P'):
        return {"type": "patch", "field": "patch_num", "api": "get_task_list"}
    # 任务编号：T开头
    elif query_value.startswith('T') and not query_value.startswith('TD'):
        return {"type": "task", "field": "task_number", "api": "get_task_info"}
    # 任务编号：TD开头
    elif query_value.startswith('TD'):
        return {"type": "task", "field": "task_number", "api": "get_task_info"}
    # 版本编号：ST/OST/ALGO开头
    elif query_value.startswith('ST') or query_value.startswith('OST') or query_value.startswith('ALGO'):
        return {"type": "version", "field": "version_no", "api": "get_version_list"}
    # 功能号：纯数字
    elif query_value.isdigit():
        return {"type": "function", "field": "function", "api": "get_case_by_function"}
    else:
        # 尝试作为需求编号查询
        return {"type": "demand", "field": "story_num", "api": "get_story_info"}
    elif query_value.startswith('ST') or query_value.startswith('OST'):
        return {"type": "patch", "field": "version_no", "api": "get_version_list"}
    elif query_value.isdigit():
        return {"type": "function", "field": "function", "api": "get_case_by_function"}
    else:
        # 尝试作为需求编号查询
        return {"type": "demand", "field": "story_num", "api": "get_story_info"}


def format_story_info(story: Dict[str, Any]) -> Dict[str, Any]:
    """格式化需求信息"""
    if not story:
        return {}

    return {
        "需求编号": story.get("story_num", ""),
        "需求标题": story.get("story_name", ""),
        "需求描述": story.get("description", ""),
        "需求背景": story.get("req_back_ground", ""),
        "客户名称": story.get("customer_name", ""),
        "产品名称": story.get("product_name", ""),
        "需求类型": story.get("story_type", ""),
        "创建时间": story.get("create_time", ""),
        "承诺发放日期": story.get("promise_date", ""),
        "审核状态": story.get("review_status", ""),
        "处理意见": story.get("suggestion", ""),
        "设计说明": story.get("design_note", ""),
        "验收标准": story.get("inspect_desc", ""),
    }


def format_task_info(task: Dict[str, Any]) -> Dict[str, Any]:
    """格式化任务信息"""
    if not task:
        return {}

    return {
        "任务编号": task.get("task_number", ""),
        "任务名称": task.get("name", ""),
        "任务类型": task.get("typeName", ""),
        "处理人": task.get("modifierName", ""),
        "状态": task.get("modifyStatusName", ""),
        "进度": f"{task.get('finish_percentage', 0) * 100}%",
        "预估工作量": task.get("estimate_workload", ""),
        "实际工作量": task.get("real_workload", ""),
        "截止日期": task.get("estimate_finish_time", ""),
        "关联需求": ",".join(task.get("story_nums", [])),
        "版本号": task.get("versionNO", ""),
        "修改说明": task.get("edit_description", ""),
        "设计方案": task.get("design_description", ""),
        "测试建议": task.get("suggestion", ""),
        "修改文件": task.get("modified_file", ""),

