time_t FUNCTION_CALL_MODE toDataTime(int Date,int iTime)
{
	int yyyy = Date/10000;
	int month = (Date - yyyy*10000)/100;
	int dd = Date - yyyy*10000 - month*100;
	int hh = iTime/10000;
	int mm = (iTime - hh *10000)/100;
	int ss = iTime - hh *10000 - mm*100;
	time_t now = time(NULL);
	tm local; //����ʱ��
	localtime_r(&now, &local);//ͨ���ú�����tm.tm_isdst��ʶ����ֹ��ֵδ��ʼ��Ӱ��mktime��ֵ
	local.tm_year=yyyy - 1900;//��ݣ�ʵ����ݼ�ȥ1900
	local.tm_mon=month-1;//�·� ��0��ʼ��ʾ1��
	local.tm_mday=dd;
	local.tm_hour=hh;
	local.tm_min=mm;
	local.tm_sec=ss;
	return mktime(&local);
}


// ������������֮���������  
int diff_in_days(time_t time1, time_t time2) {  


	// ȷ��time2����time1���Ա�õ��������
	if (time2 < time1) {
		time_t temp = time1;
		time1 = time2;
		time2 = temp;
	}

	// �����ֵ��ת��Ϊ����
	double diff_in_seconds = difftime(time2, time1);
	int diff_in_days = (int)(diff_in_seconds / (60 * 60 * 24)); // 1�� = 60�� * 60�� * 24Сʱ

	return diff_in_days;
} 

